def build():
    assert len(Q) == 80, len(Q)
    fixed = [L for b, _, _, idx, _, _ in Q if b == 'bozan' for L in ['ABCDE'[idx]]]
    need = []
    for L in 'ABCDE':
        need += [L] * (16 - fixed.count(L))
    random.Random(2026).shuffle(need)
    it = iter(need)
    out, gruplar = [], {}
    for no, (bolum, kok, dogru, celdirici, cozum, grup) in enumerate(Q, start=1):
        if bolum == 'bozan':
            secenekler, cevap = ROMAN[:], 'ABCDE'[celdirici]
        else:
            assert len(celdirici) == 4 and dogru not in celdirici and len(set(celdirici)) == 4, no
            cevap = next(it)
            rest = iter(celdirici)
            secenekler = [dogru if L == cevap else next(rest) for L in 'ABCDE']
        if grup:
            gruplar[grup] = GRUP[grup]
            if bolum == 'cloze':
                assert f'({no}) ----' in GRUP[grup], (no, grup)
        out.append({'no': no, 'bolum': bolum, 'konu': KONU[bolum], 'yonerge': YONERGE[bolum], 'grup': grup,
                    'metin': kok, 'secenekler': secenekler, 'cevap': cevap, 'cozum': cozum})
    counts = {L: sum(1 for q in out if q['cevap'] == L) for L in 'ABCDE'}
    assert all(v == 16 for v in counts.values()), counts
    data = {'kaynak': KAYNAK, 'gruplar': gruplar, 'sorular': out}
    path = Path(__file__).with_name('yds-deneme-1.json')
    path.write_text(json.dumps(data, ensure_ascii=False, indent=1), encoding='utf-8')
    print(f'yazıldı: {path} · {len(out)} soru · cevap dağılımı {counts}')


if __name__ == '__main__':
    build()
